def shell_escape_path(p):
    return shlex.quote(p)

def command_hash(cmd):
    # A stable 64-bit hash, formatted like ninja's log hashes.  The exact
    # algorithm is internal; for this reimplementation stability is what the
    # build logic needs.
    return hashlib.blake2b(cmd.encode('utf-8'), digest_size=8).hexdigest()

class NinjaError(Exception):
