class Env:
    def __init__(self, parent=None):
        self.parent = parent
        self.vars = OrderedDict()
    def get(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.get(name)
        return ""
    def set(self, name, val):
