# ---------------- lexer / expansion ----------------

def strip_comment(line):
    # Comments begin with an unescaped #.  A $ before it quotes it.
    i = 0
    res = []
    while i < len(line):
        c = line[i]
        if c == '$' and i + 1 < len(line):
            res.append(c); res.append(line[i+1]); i += 2; continue
        if c == '#':
            break
        res.append(c); i += 1
    return ''.join(res).rstrip()

def join_continuations(text):
    phys = text.splitlines(True)
    logical = []
    cur = ''
    start_line = 1
    line_no = 1
    for raw in phys:
        s = raw.rstrip('\n')
        if s.endswith('\r'):
            s = s[:-1]
        if cur == '':
            start_line = line_no
        if s.endswith('$'):
            cur += s[:-1]
            # Continuation consumes following indentation.
        else:
            if cur:
                cur += s.lstrip(' \t')
                logical.append((start_line, cur))
                cur = ''
            else:
                logical.append((line_no, s))
        line_no += 1
    if cur:
        logical.append((start_line, cur))
    return logical

def expand_string(raw, env, special=None, shell_paths=False, raw_paths=False):
    """Expand ninja $ syntax.

    special maps in/out/etc to either strings or lists of paths.  When
    shell_paths is true, list-valued specials are joined with POSIX shell
    quoting, matching Ninja's command-line expansion on Unix.
    """
    special = special or {}
    def val(name):
        if name in special:
            v = special[name]
            if isinstance(v, list):
                if raw_paths:
                    return ' '.join(v)
                if shell_paths:
                    return ' '.join(shell_escape_path(x) for x in v)
                return ' '.join(v)
            return str(v)
        return env.get(name)
    res = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c != '$':
            res.append(c); i += 1; continue
        i += 1
        if i >= len(raw):
            # Ninja treats a trailing $ as an error during lexing; keep it
            # literal for robustness.
            res.append('$'); break
        c2 = raw[i]
        if c2 == '$':
            res.append('$'); i += 1
        elif c2 == ' ':
            res.append(' '); i += 1
        elif c2 == ':':
            res.append(':'); i += 1
        elif c2 == '\n':
            i += 1
        elif c2 == '{':
            j = raw.find('}', i+1)
            if j == -1:
                name = raw[i+1:]
                i = len(raw)
            else:
                name = raw[i+1:j]
                i = j + 1
            res.append(val(name))
        else:
            j = i
            while j < len(raw) and (raw[j].isalnum() or raw[j] in '_.-'):
                j += 1
            if j == i:
