                res.append(c2); i += 1
            else:
                res.append(val(raw[i:j])); i = j
    return ''.join(res)

def split_words_ninja(raw, env):
    """Split a ninja path list.  Variable expansion may contribute words;
    escaped spaces ($ ) stay inside the current word.
    """
    tokens = []
    cur = []
    def flush():
        nonlocal cur
        if cur:
            tokens.append(''.join(cur)); cur = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c in ' \t':
            flush(); i += 1; continue
        if c == '$':
            i += 1
            if i >= len(raw):
                cur.append('$'); break
            c2 = raw[i]
            if c2 == ' ':
                cur.append(' '); i += 1
            elif c2 == ':':
                cur.append(':'); i += 1
            elif c2 == '$':
                cur.append('$'); i += 1
            elif c2 == '{':
                j = raw.find('}', i+1)
                if j == -1:
                    name = raw[i+1:]; i = len(raw)
                else:
                    name = raw[i+1:j]; i = j+1
                expanded = env.get(name)
                # Expanded values are re-lexed as ordinary path lists.
                subtoks = split_words_ninja(expanded, Env()) if expanded else []
                if subtoks:
                    if cur:
                        cur.append(subtoks[0])
                    else:
                        cur = [subtoks[0]]
                    for t in subtoks[1:]:
                        flush(); cur = [t]
            else:
                j = i
                while j < len(raw) and (raw[j].isalnum() or raw[j] in '_.-'):
                    j += 1
                if j == i:
                    cur.append(c2); i += 1
                else:
                    expanded = env.get(raw[i:j]); i = j
                    subtoks = split_words_ninja(expanded, Env()) if expanded else []
                    if subtoks:
                        if cur:
                            cur.append(subtoks[0])
                        else:
                            cur = [subtoks[0]]
                        for t in subtoks[1:]:
                            flush(); cur = [t]
