                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' not in l2:
                        raise NinjaError(f"{filename}:{ln}: expected variable binding")
                    k, v = l2.split('=', 1)
                    r.bindings[k.strip()] = v.strip()
                self.m.add_rule(r)
            elif st.startswith('pool '):
                name = st[5:].strip()
                depth = 0
                while i < len(lines):
                    ln, raw2 = lines[i]
                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' in l2:
                        k, v = l2.split('=', 1)
                        if k.strip() == 'depth':
                            try: depth = int(expand_string(v.strip(), env))
                            except ValueError: depth = 0
                self.m.pools[name] = depth
            elif st.startswith('build '):
                edge = self.parse_build(st[6:].strip(), env, filename, line_no)
                while i < len(lines):
                    ln, raw2 = lines[i]
                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' not in l2:
                        raise NinjaError(f"{filename}:{ln}: expected variable binding")
                    k, v = l2.split('=', 1)
