                    # non-special environment.
                    edge.bindings[k.strip()] = expand_string(v.strip(), env)
                self.finish_edge(edge)
            elif st.startswith('default '):
                for p in split_words_ninja(st[8:].strip(), env):
                    self.m.defaults.append(self.m.node(p))
            elif st.startswith('include '):
                inc = expand_string(st[8:].strip(), env)
                path = inc if os.path.isabs(inc) else os.path.join(base, inc)
                self.parse_file(path, env)
            elif st.startswith('subninja '):
                sub = expand_string(st[9:].strip(), env)
                path = sub if os.path.isabs(sub) else os.path.join(base, sub)
                self.parse_file(path, Env(env))
            elif '=' in st:
                k, v = st.split('=', 1)
                key = k.strip(); val = expand_string(v.strip(), env)
                env.set(key, val)
                if key == 'builddir':
                    self.m.builddir = val
                if key == 'ninja_required_version':
                    # This implementation is compatible with documented syntax.
                    pass
            else:
                raise NinjaError(f"{filename}:{line_no}: expected build command name")
    def parse_build(self, rest, env, filename, line_no):
        toks = split_words_ninja(rest, env)
