        mode='outs'
        rule_name=None
        idx=0
        while idx < len(toks):
            t = toks[idx]
            if mode == 'outs':
                if t == '|': mode='implicit_outs'
                elif t == ':': mode='rule'; idx += 1; break
                else: outs.append(t)
            elif mode == 'implicit_outs':
                if t == ':': mode='rule'; idx += 1; break
                else: implicit_outs.append(t)
