        e.implicit_outputs = [self.m.node(p) for p in implicit_outs]
        e.inputs = [self.m.node(p) for p in ins]
        e.implicit_inputs = [self.m.node(p) for p in implicit]
        e.order_only = [self.m.node(p) for p in order]
        e.validations = [self.m.node(p) for p in validations]
        return e
