        for n in e.all_outputs:
            if n.in_edge is not None and e.rule.name != 'phony':
                # Ninja diagnoses duplicate rules; for simplicity keep latest.
                pass
            n.in_edge = e
        for n in e.all_inputs_for_build + e.validations:
            n.out_edges.append(e)

def split_build_punct(raw, env):
    # Like split_words_ninja but unescaped ':', '|', '||', '|@' are separate.
    toks=[]; cur=[]; i=0
    def flush():
        nonlocal cur
        if cur:
            toks.append(''.join(cur)); cur=[]
    while i < len(raw):
        c=raw[i]
        if c in ' \t': flush(); i+=1; continue
        if c == ':': flush(); toks.append(':'); i+=1; continue
        if c == '|':
            flush()
            if i+1 < len(raw) and raw[i+1] == '|': toks.append('||'); i+=2
            elif i+1 < len(raw) and raw[i+1] == '@': toks.append('|@'); i+=2
            else: toks.append('|'); i+=1
            continue
        if c == '$':
            i+=1
            if i>=len(raw): cur.append('$'); break
            c2=raw[i]
            if c2 == ' ': cur.append(' '); i+=1
            elif c2 == ':': cur.append(':'); i+=1
            elif c2 == '$': cur.append('$'); i+=1
            elif c2 == '{':
                j=raw.find('}', i+1)
                if j == -1: name=raw[i+1:]; i=len(raw)
                else: name=raw[i+1:j]; i=j+1
                exp=env.get(name); sub=split_build_punct(exp, Env()) if exp else []
                if sub:
                    if cur: cur.append(sub[0])
                    else: cur=[sub[0]]
                    for t in sub[1:]: flush(); cur=[t]
            else:
                j=i
                while j<len(raw) and (raw[j].isalnum() or raw[j] in '_.-'): j+=1
                if j==i: cur.append(c2); i+=1
                else:
                    exp=env.get(raw[i:j]); i=j; sub=split_build_punct(exp, Env()) if exp else []
                    if sub:
                        if cur: cur.append(sub[0])
                        else: cur=[sub[0]]
                        for t in sub[1:]: flush(); cur=[t]
        else:
            cur.append(c); i+=1
    flush(); return toks

# ---------------- evaluation ----------------

def special_for_edge(e):
    return {
        'in': [n.path for n in e.inputs],
        'in_newline': '\n'.join(n.path for n in e.inputs),
        'out': [n.path for n in e.outputs],
    }

def edge_lookup(e, name):
    if name in e.bindings:
        return e.bindings[name]
    if name in e.rule.bindings:
        return e.rule.bindings[name]
    return e.env.get(name)

def expand_edge_binding(e, name, shell_paths=True, raw_paths=False):
    raw = edge_lookup(e, name)
    if raw == "": return ""
    # Environment for ordinary variables: edge bindings shadow globals/rule.
    class EdgeEnv:
        def get(self_inner, k):
            if k in ('in','out','in_newline'):
                v = special_for_edge(e)[k]
                if k == 'in_newline': return v
                return ' '.join(v) if raw_paths else ' '.join(shell_escape_path(x) for x in v) if shell_paths else ' '.join(v)
            if k in e.bindings: return e.bindings[k]
            return e.env.get(k)
    return expand_string(raw, EdgeEnv(), special_for_edge(e), shell_paths=shell_paths, raw_paths=raw_paths)

def edge_command(e):
    return expand_edge_binding(e, 'command', shell_paths=True)

def edge_description(e, verbose=False):
    if verbose:
        return edge_command(e)
    d = expand_edge_binding(e, 'description', shell_paths=True)
    return d if d else edge_command(e)

def log_path(manifest):
    if manifest.builddir:
        try: os.makedirs(manifest.builddir, exist_ok=True)
        except OSError: pass
        return os.path.join(manifest.builddir, '.ninja_log')
    return '.ninja_log'

def load_log(manifest):
    d={}
    p=log_path(manifest)
    try:
        with open(p, 'r', encoding='utf-8') as f:
            for line in f:
                if line.startswith('#') or not line.strip(): continue
                parts=line.rstrip('\n').split('\t')
                if len(parts) >= 5:
                    try: d[parts[3]]=(int(parts[0]), int(parts[1]), parts[4])
                    except ValueError: d[parts[3]]=(0,0,parts[4])
    except OSError:
        pass
    return d

def append_log(manifest, e, start_ns, end_ns, cmd):
    p=log_path(manifest)
    exists=os.path.exists(p)
    with open(p, 'a', encoding='utf-8') as f:
        if not exists:
            f.write('# ninja log v7\n')
        h=command_hash(cmd)
        # Ninja logs millisecond start/end relative to invocation plus mtime in
        # older versions; observed v7 logs nanosecond-ish times.  Use elapsed ms
        # for the first fields; rebuild decisions use only the hash below.
        s=int(start_ns/1_000_000); e_ns=int(end_ns/1_000_000)
        for n in e.all_outputs:
            f.write(f"{s}\t{e_ns}\t{mtime_ns(n.path)}\t{n.path}\t{h}\n")

def mtime_ns(path):
    try: return os.stat(path).st_mtime_ns
    except OSError: return 0

def path_exists(path):
    return os.path.exists(path)

class Builder:
    def __init__(self, manifest, opts):
        self.m=manifest; self.opts=opts; self.log=load_log(manifest)
        self.explain=[]
        self.dirty_cache={}
        self.visiting=set(); self.plan=[]; self.plan_set=set()
        self.missing_error=None
    def node_mtime(self, n):
        if n.in_edge and n.in_edge.rule.name == 'phony' and not path_exists(n.path):
            if not n.in_edge.all_inputs_for_build:
                return 0
            return max((self.node_mtime(x) for x in n.in_edge.all_inputs_for_build), default=0)
        return mtime_ns(n.path)
    def check_missing_source(self, n, needed_by):
        if n.in_edge is None and not path_exists(n.path):
            self.missing_error = f"'{n.path}', needed by '{needed_by.path}', missing and no known rule to make it"
            return False
        return True
    def edge_dirty(self, e):
        if e.rule.name == 'phony':
            return False
        key=e.index
        if key in self.dirty_cache: return self.dirty_cache[key]
        dirty=False
        outputs=e.all_outputs
        out_mtimes=[mtime_ns(n.path) for n in outputs]
        if not outputs:
            dirty=False
        elif any(t == 0 for t in out_mtimes):
            dirty=True
        min_out=min([t for t in out_mtimes if t] or [0])
        # Explicit and implicit inputs affect timestamp.  Order-only only has to
        # be buildable; it does not make outputs dirty solely by timestamp.
        for n in e.inputs + e.implicit_inputs:
            if n.in_edge and self.edge_dirty(n.in_edge):
                dirty=True
            mt=self.node_mtime(n)
            if mt and min_out and mt > min_out:
                dirty=True
            if n.in_edge is None and not path_exists(n.path):
                self.check_missing_source(n, outputs[0] if outputs else n)
        for n in e.order_only:
            if n.in_edge and self.edge_dirty(n.in_edge): dirty=True
            elif n.in_edge is None and not path_exists(n.path): self.check_missing_source(n, outputs[0] if outputs else n)
        cmd=edge_command(e)
        h=command_hash(cmd)
        for n in outputs:
            ent=self.log.get(n.path)
            if ent is None and path_exists(n.path):
                # Existing file with no log entry is accepted unless inputs are newer.
                continue
            if ent is not None and ent[2] != h:
                dirty=True
        self.dirty_cache[key]=dirty
        return dirty
    def visit_node(self, n, require=True):
        e=n.in_edge
        if e is None:
            if require and not path_exists(n.path):
                self.missing_error = f"'{n.path}', needed by target, missing and no known rule to make it"
                return
            return
        if e.index in self.visiting: return
        self.visiting.add(e.index)
        # Missing source diagnostics should name the immediate output.
        for inp in e.all_inputs_for_build:
            if inp.in_edge is None and not path_exists(inp.path):
                if e.rule.name == 'phony' and inp.path == n.path:
                    continue
                self.missing_error = f"'{inp.path}', needed by '{e.outputs[0].path if e.outputs else n.path}', missing and no known rule to make it"
                return
            self.visit_node(inp, True)
            if self.missing_error: return
