  stats        print operation counts/timing info
  explain      explain what caused a command to execute
  keepdepfile  don't delete depfiles after they're read by ninja
  keeprsp      don't delete @response files on success
multiple modes can be enabled via -d FOO -d BAR
"""
WARN_LIST = """warning flags:
  phonycycle={err,warn}  phony build statement references itself
"""
TOOL_LIST = """ninja subtools:
     browse  browse dependency graph in a web browser
      clean  clean built files
   commands  list all commands required to rebuild given targets
     inputs  list all inputs required to rebuild given targets
multi-inputs  print one or more sets of inputs required to build targets
       deps  show dependencies stored in the deps log
missingdeps  check deps log dependencies on generated files
      graph  output graphviz dot file for targets
      query  show inputs/outputs for a path
    targets  list targets by their rule or depth in the DAG
     compdb  dump JSON compilation database to stdout
compdb-targets  dump JSON compilation database for a given list of targets to stdout
  recompact  recompacts ninja-internal data structures
     restat  restats all outputs in the build log
      rules  list all rules
  cleandead  clean built files that are no longer produced by the manifest
"""

def eprint(s):
    sys.stderr.write(s)

def out(s):
    sys.stdout.write(s)

def shell_escape_path(p):
    return shlex.quote(p)

def command_hash(cmd):
    # A stable 64-bit hash, formatted like ninja's log hashes.  The exact
    # algorithm is internal; for this reimplementation stability is what the
    # build logic needs.
    return hashlib.blake2b(cmd.encode('utf-8'), digest_size=8).hexdigest()

class NinjaError(Exception):
    pass

class Env:
    def __init__(self, parent=None):
        self.parent = parent
        self.vars = OrderedDict()
    def get(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.get(name)
        return ""
    def set(self, name, val):
        self.vars[name] = val

class Rule:
    def __init__(self, name):
        self.name = name
        self.bindings = OrderedDict()

class Node:
    def __init__(self, path):
        self.path = path
        self.in_edge = None
        self.out_edges = []

class Edge:
    def __init__(self, index, rule, env):
        self.index = index
        self.rule = rule
        self.env = env
        self.outputs = []
        self.implicit_outputs = []
        self.inputs = []
        self.implicit_inputs = []
        self.order_only = []
        self.validations = []
        self.bindings = OrderedDict()
    @property
    def all_outputs(self):
        return self.outputs + self.implicit_outputs
    @property
    def all_inputs_for_build(self):
        return self.inputs + self.implicit_inputs + self.order_only
    @property
    def dep_inputs(self):
        return self.inputs + self.implicit_inputs

class Manifest:
    def __init__(self):
        self.root_env = Env()
        self.rules = OrderedDict()
        self.rules['phony'] = Rule('phony')
        self.nodes = OrderedDict()
        self.edges = []
        self.defaults = []
        self.pools = {'console': 1}
        self.builddir = None
        self.file_stack = []
    def node(self, path):
        if path not in self.nodes:
            self.nodes[path] = Node(path)
        return self.nodes[path]
    def add_rule(self, r):
        self.rules[r.name] = r

# ---------------- lexer / expansion ----------------

def strip_comment(line):
    # Comments begin with an unescaped #.  A $ before it quotes it.
    i = 0
    res = []
    while i < len(line):
        c = line[i]
        if c == '$' and i + 1 < len(line):
            res.append(c); res.append(line[i+1]); i += 2; continue
        if c == '#':
            break
        res.append(c); i += 1
    return ''.join(res).rstrip()

def join_continuations(text):
    phys = text.splitlines(True)
    logical = []
    cur = ''
    start_line = 1
    line_no = 1
    for raw in phys:
        s = raw.rstrip('\n')
        if s.endswith('\r'):
            s = s[:-1]
        if cur == '':
            start_line = line_no
        if s.endswith('$'):
            cur += s[:-1]
            # Continuation consumes following indentation.
        else:
            if cur:
                cur += s.lstrip(' \t')
                logical.append((start_line, cur))
                cur = ''
            else:
                logical.append((line_no, s))
        line_no += 1
    if cur:
        logical.append((start_line, cur))
    return logical

def expand_string(raw, env, special=None, shell_paths=False, raw_paths=False):
    """Expand ninja $ syntax.

    special maps in/out/etc to either strings or lists of paths.  When
    shell_paths is true, list-valued specials are joined with POSIX shell
    quoting, matching Ninja's command-line expansion on Unix.
    """
    special = special or {}
    def val(name):
        if name in special:
            v = special[name]
            if isinstance(v, list):
                if raw_paths:
                    return ' '.join(v)
                if shell_paths:
                    return ' '.join(shell_escape_path(x) for x in v)
                return ' '.join(v)
            return str(v)
        return env.get(name)
    res = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c != '$':
            res.append(c); i += 1; continue
        i += 1
        if i >= len(raw):
            # Ninja treats a trailing $ as an error during lexing; keep it
            # literal for robustness.
            res.append('$'); break
        c2 = raw[i]
        if c2 == '$':
            res.append('$'); i += 1
        elif c2 == ' ':
            res.append(' '); i += 1
        elif c2 == ':':
            res.append(':'); i += 1
        elif c2 == '\n':
            i += 1
        elif c2 == '{':
            j = raw.find('}', i+1)
            if j == -1:
                name = raw[i+1:]
                i = len(raw)
            else:
                name = raw[i+1:j]
                i = j + 1
            res.append(val(name))
        else:
            j = i
            while j < len(raw) and (raw[j].isalnum() or raw[j] in '_.-'):
                j += 1
            if j == i:
                # Unknown escape, preserve the escaped character.
                res.append(c2); i += 1
            else:
                res.append(val(raw[i:j])); i = j
    return ''.join(res)

def split_words_ninja(raw, env):
    """Split a ninja path list.  Variable expansion may contribute words;
    escaped spaces ($ ) stay inside the current word.
    """
    tokens = []
    cur = []
    def flush():
        nonlocal cur
        if cur:
            tokens.append(''.join(cur)); cur = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c in ' \t':
            flush(); i += 1; continue
        if c == '$':
            i += 1
            if i >= len(raw):
                cur.append('$'); break
            c2 = raw[i]
            if c2 == ' ':
                cur.append(' '); i += 1
            elif c2 == ':':
                cur.append(':'); i += 1
            elif c2 == '$':
                cur.append('$'); i += 1
            elif c2 == '{':
                j = raw.find('}', i+1)
                if j == -1:
                    name = raw[i+1:]; i = len(raw)
                else:
                    name = raw[i+1:j]; i = j+1
                expanded = env.get(name)
                # Expanded values are re-lexed as ordinary path lists.
                subtoks = split_words_ninja(expanded, Env()) if expanded else []
                if subtoks:
                    if cur:
                        cur.append(subtoks[0])
                    else:
                        cur = [subtoks[0]]
                    for t in subtoks[1:]:
                        flush(); cur = [t]
            else:
                j = i
                while j < len(raw) and (raw[j].isalnum() or raw[j] in '_.-'):
                    j += 1
                if j == i:
                    cur.append(c2); i += 1
                else:
                    expanded = env.get(raw[i:j]); i = j
                    subtoks = split_words_ninja(expanded, Env()) if expanded else []
                    if subtoks:
                        if cur:
                            cur.append(subtoks[0])
                        else:
                            cur = [subtoks[0]]
                        for t in subtoks[1:]:
                            flush(); cur = [t]
        else:
            cur.append(c); i += 1
    flush()
    return tokens

# ---------------- parser ----------------

class Parser:
    def __init__(self, manifest):
        self.m = manifest
    def parse_file(self, filename, env=None):
        if env is None: env = self.m.root_env
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                text = f.read()
        except OSError as e:
            raise NinjaError(f"loading '{filename}': {e.strerror}")
        old_dir = os.getcwd()
        base = os.path.dirname(filename)
        # Includes are relative to the including file's directory.  Ninja also
        # keeps build paths relative to cwd; we simply open via joined paths.
        lines = join_continuations(text)
        i = 0
        while i < len(lines):
            line_no, raw = lines[i]
            line = strip_comment(raw)
            i += 1
            if not line.strip():
                continue
            if line[0] in ' \t':
                raise NinjaError(f"{filename}:{line_no}: unexpected indent")
            st = line.strip()
            if st.startswith('rule '):
                name = st[5:].strip()
                r = Rule(name)
                while i < len(lines):
                    ln, raw2 = lines[i]
                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' not in l2:
                        raise NinjaError(f"{filename}:{ln}: expected variable binding")
                    k, v = l2.split('=', 1)
                    r.bindings[k.strip()] = v.strip()
                self.m.add_rule(r)
            elif st.startswith('pool '):
                name = st[5:].strip()
                depth = 0
                while i < len(lines):
                    ln, raw2 = lines[i]
                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' in l2:
                        k, v = l2.split('=', 1)
                        if k.strip() == 'depth':
                            try: depth = int(expand_string(v.strip(), env))
                            except ValueError: depth = 0
                self.m.pools[name] = depth
            elif st.startswith('build '):
                edge = self.parse_build(st[6:].strip(), env, filename, line_no)
                while i < len(lines):
                    ln, raw2 = lines[i]
                    if not raw2 or raw2[0] not in ' \t': break
                    i += 1
                    l2 = strip_comment(raw2).strip()
                    if not l2: continue
                    if '=' not in l2:
                        raise NinjaError(f"{filename}:{ln}: expected variable binding")
                    k, v = l2.split('=', 1)
                    # Edge-local bindings are expanded when read in the current
                    # non-special environment.
                    edge.bindings[k.strip()] = expand_string(v.strip(), env)
                self.finish_edge(edge)
            elif st.startswith('default '):
                for p in split_words_ninja(st[8:].strip(), env):
                    self.m.defaults.append(self.m.node(p))
            elif st.startswith('include '):
                inc = expand_string(st[8:].strip(), env)
                path = inc if os.path.isabs(inc) else os.path.join(base, inc)
                self.parse_file(path, env)
            elif st.startswith('subninja '):
                sub = expand_string(st[9:].strip(), env)
                path = sub if os.path.isabs(sub) else os.path.join(base, sub)
                self.parse_file(path, Env(env))
            elif '=' in st:
                k, v = st.split('=', 1)
                key = k.strip(); val = expand_string(v.strip(), env)
                env.set(key, val)
                if key == 'builddir':
                    self.m.builddir = val
                if key == 'ninja_required_version':
                    # This implementation is compatible with documented syntax.
                    pass
            else:
                raise NinjaError(f"{filename}:{line_no}: expected build command name")
    def parse_build(self, rest, env, filename, line_no):
        toks = split_words_ninja(rest, env)
        if ':' not in toks:
            # colon can appear as a token only when unescaped; because our
            # splitter does not split punctuation, do a secondary pass for ':'
            toks = split_build_punct(rest, env)
        else:
            toks = split_build_punct(rest, env)
        outs=[]; implicit_outs=[]; ins=[]; implicit=[]; order=[]; validations=[]
        mode='outs'
        rule_name=None
        idx=0
        while idx < len(toks):
            t = toks[idx]
            if mode == 'outs':
                if t == '|': mode='implicit_outs'
                elif t == ':': mode='rule'; idx += 1; break
                else: outs.append(t)
            elif mode == 'implicit_outs':
                if t == ':': mode='rule'; idx += 1; break
                else: implicit_outs.append(t)
            idx += 1
        if mode != 'rule' or idx > len(toks) or idx == 0:
            raise NinjaError(f"{filename}:{line_no}: expected ':' in build statement")
        if idx >= len(toks):
            raise NinjaError(f"{filename}:{line_no}: expected rule name")
        rule_name = toks[idx]; idx += 1
        mode='ins'
        while idx < len(toks):
            t = toks[idx]
            if t == '|': mode='implicit'
            elif t == '||': mode='order'
            elif t == '|@': mode='validations'
            else:
                if mode == 'ins': ins.append(t)
                elif mode == 'implicit': implicit.append(t)
                elif mode == 'order': order.append(t)
                else: validations.append(t)
            idx += 1
        if rule_name not in self.m.rules:
            raise NinjaError(f"{filename}:{line_no}: unknown build rule '{rule_name}'")
        e = Edge(len(self.m.edges), self.m.rules[rule_name], env)
        e.outputs = [self.m.node(p) for p in outs]
        e.implicit_outputs = [self.m.node(p) for p in implicit_outs]
        e.inputs = [self.m.node(p) for p in ins]
        e.implicit_inputs = [self.m.node(p) for p in implicit]
        e.order_only = [self.m.node(p) for p in order]
        e.validations = [self.m.node(p) for p in validations]
        return e
    def finish_edge(self, e):
        self.m.edges.append(e)
        for n in e.all_outputs:
            if n.in_edge is not None and e.rule.name != 'phony':
                # Ninja diagnoses duplicate rules; for simplicity keep latest.
                pass
            n.in_edge = e
        for n in e.all_inputs_for_build + e.validations:
            n.out_edges.append(e)

def split_build_punct(raw, env):
    # Like split_words_ninja but unescaped ':', '|', '||', '|@' are separate.
    toks=[]; cur=[]; i=0
    def flush():
        nonlocal cur
        if cur:
            toks.append(''.join(cur)); cur=[]
    while i < len(raw):
        c=raw[i]
        if c in ' \t': flush(); i+=1; continue
        if c == ':': flush(); toks.append(':'); i+=1; continue
        if c == '|':
            flush()
            if i+1 < len(raw) and raw[i+1] == '|': toks.append('||'); i+=2
            elif i+1 < len(raw) and raw[i+1] == '@': toks.append('|@'); i+=2
            else: toks.append('|'); i+=1
            continue
        if c == '$':
            i+=1
            if i>=len(raw): cur.append('$'); break
            c2=raw[i]
            if c2 == ' ': cur.append(' '); i+=1
            elif c2 == ':': cur.append(':'); i+=1
            elif c2 == '$': cur.append('$'); i+=1
            elif c2 == '{':
                j=raw.find('}', i+1)
                if j == -1: name=raw[i+1:]; i=len(raw)
                else: name=raw[i+1:j]; i=j+1
                exp=env.get(name); sub=split_build_punct(exp, Env()) if exp else []
                if sub:
                    if cur: cur.append(sub[0])
                    else: cur=[sub[0]]
                    for t in sub[1:]: flush(); cur=[t]
            else:
                j=i
                while j<len(raw) and (raw[j].isalnum() or raw[j] in '_.-'): j+=1
                if j==i: cur.append(c2); i+=1
                else:
                    exp=env.get(raw[i:j]); i=j; sub=split_build_punct(exp, Env()) if exp else []
                    if sub:
                        if cur: cur.append(sub[0])
                        else: cur=[sub[0]]
                        for t in sub[1:]: flush(); cur=[t]
        else:
            cur.append(c); i+=1
    flush(); return toks

# ---------------- evaluation ----------------

def special_for_edge(e):
    return {
        'in': [n.path for n in e.inputs],
        'in_newline': '\n'.join(n.path for n in e.inputs),
        'out': [n.path for n in e.outputs],
    }

def edge_lookup(e, name):
    if name in e.bindings:
        return e.bindings[name]
    if name in e.rule.bindings:
        return e.rule.bindings[name]
    return e.env.get(name)

def expand_edge_binding(e, name, shell_paths=True, raw_paths=False):
    raw = edge_lookup(e, name)
    if raw == "": return ""
    # Environment for ordinary variables: edge bindings shadow globals/rule.
    class EdgeEnv:
        def get(self_inner, k):
            if k in ('in','out','in_newline'):
                v = special_for_edge(e)[k]
                if k == 'in_newline': return v
                return ' '.join(v) if raw_paths else ' '.join(shell_escape_path(x) for x in v) if shell_paths else ' '.join(v)
            if k in e.bindings: return e.bindings[k]
            return e.env.get(k)
    return expand_string(raw, EdgeEnv(), special_for_edge(e), shell_paths=shell_paths, raw_paths=raw_paths)

def edge_command(e):
    return expand_edge_binding(e, 'command', shell_paths=True)

def edge_description(e, verbose=False):
    if verbose:
        return edge_command(e)
    d = expand_edge_binding(e, 'description', shell_paths=True)
    return d if d else edge_command(e)

def log_path(manifest):
    if manifest.builddir:
        try: os.makedirs(manifest.builddir, exist_ok=True)
        except OSError: pass
        return os.path.join(manifest.builddir, '.ninja_log')
    return '.ninja_log'

def load_log(manifest):
    d={}
    p=log_path(manifest)
    try:
        with open(p, 'r', encoding='utf-8') as f:
            for line in f:
                if line.startswith('#') or not line.strip(): continue
                parts=line.rstrip('\n').split('\t')
                if len(parts) >= 5:
                    try: d[parts[3]]=(int(parts[0]), int(parts[1]), parts[4])
                    except ValueError: d[parts[3]]=(0,0,parts[4])
    except OSError:
        pass
    return d

def append_log(manifest, e, start_ns, end_ns, cmd):
    p=log_path(manifest)
    exists=os.path.exists(p)
    with open(p, 'a', encoding='utf-8') as f:
        if not exists:
            f.write('# ninja log v7\n')
        h=command_hash(cmd)
        # Ninja logs millisecond start/end relative to invocation plus mtime in
        # older versions; observed v7 logs nanosecond-ish times.  Use elapsed ms
        # for the first fields; rebuild decisions use only the hash below.
        s=int(start_ns/1_000_000); e_ns=int(end_ns/1_000_000)
        for n in e.all_outputs:
            f.write(f"{s}\t{e_ns}\t{mtime_ns(n.path)}\t{n.path}\t{h}\n")

def mtime_ns(path):
    try: return os.stat(path).st_mtime_ns
    except OSError: return 0

def path_exists(path):
    return os.path.exists(path)

class Builder:
    def __init__(self, manifest, opts):
        self.m=manifest; self.opts=opts; self.log=load_log(manifest)
        self.explain=[]
        self.dirty_cache={}
        self.visiting=set(); self.plan=[]; self.plan_set=set()
        self.missing_error=None
    def node_mtime(self, n):
        if n.in_edge and n.in_edge.rule.name == 'phony' and not path_exists(n.path):
            if not n.in_edge.all_inputs_for_build:
                return 0
            return max((self.node_mtime(x) for x in n.in_edge.all_inputs_for_build), default=0)
        return mtime_ns(n.path)
    def check_missing_source(self, n, needed_by):
        if n.in_edge is None and not path_exists(n.path):
            self.missing_error = f"'{n.path}', needed by '{needed_by.path}', missing and no known rule to make it"
            return False
        return True
    def edge_dirty(self, e):
        if e.rule.name == 'phony':
            return False
        key=e.index
        if key in self.dirty_cache: return self.dirty_cache[key]
        dirty=False
        outputs=e.all_outputs
        out_mtimes=[mtime_ns(n.path) for n in outputs]
        if not outputs:
            dirty=False
        elif any(t == 0 for t in out_mtimes):
            dirty=True
        min_out=min([t for t in out_mtimes if t] or [0])
        # Explicit and implicit inputs affect timestamp.  Order-only only has to
        # be buildable; it does not make outputs dirty solely by timestamp.
        for n in e.inputs + e.implicit_inputs:
            if n.in_edge and self.edge_dirty(n.in_edge):
                dirty=True
            mt=self.node_mtime(n)
            if mt and min_out and mt > min_out:
                dirty=True
            if n.in_edge is None and not path_exists(n.path):
                self.check_missing_source(n, outputs[0] if outputs else n)
        for n in e.order_only:
            if n.in_edge and self.edge_dirty(n.in_edge): dirty=True
            elif n.in_edge is None and not path_exists(n.path): self.check_missing_source(n, outputs[0] if outputs else n)
        cmd=edge_command(e)
        h=command_hash(cmd)
        for n in outputs:
            ent=self.log.get(n.path)
            if ent is None and path_exists(n.path):
                # Existing file with no log entry is accepted unless inputs are newer.
                continue
            if ent is not None and ent[2] != h:
                dirty=True
        self.dirty_cache[key]=dirty
        return dirty
    def visit_node(self, n, require=True):
        e=n.in_edge
        if e is None:
            if require and not path_exists(n.path):
                self.missing_error = f"'{n.path}', needed by target, missing and no known rule to make it"
                return
            return
        if e.index in self.visiting: return
        self.visiting.add(e.index)
        # Missing source diagnostics should name the immediate output.
        for inp in e.all_inputs_for_build:
            if inp.in_edge is None and not path_exists(inp.path):
                if e.rule.name == 'phony' and inp.path == n.path:
                    continue
                self.missing_error = f"'{inp.path}', needed by '{e.outputs[0].path if e.outputs else n.path}', missing and no known rule to make it"
                return
            self.visit_node(inp, True)
            if self.missing_error: return
        self.visiting.remove(e.index)
        if e.rule.name != 'phony' and self.edge_dirty(e) and e.index not in self.plan_set:
            self.plan.append(e); self.plan_set.add(e.index)
    def build(self, targets):
        if not targets:
            if self.m.defaults:
                targets = self.m.defaults
            else:
                targets = root_targets(self.m)
        for n in targets:
            self.visit_node(n, True)
            if self.missing_error: raise NinjaError(self.missing_error)
        total=len(self.plan)
        if total == 0:
            if not self.opts.get('quiet'):
                out('ninja: no work to do.\n')
            return 0
        done_edges=set(); failed=0; last_rc=0; started=0; finished=0
        pending=list(self.plan)
        # Wave scheduler: in each pass run the edges that were already ready at
        # the beginning of the pass. This matches Ninja's common output ordering
        # for parallel-ready builds while keeping implementation simple.
        while pending:
            wave=[]
            for e in list(pending):
                if all((inp.in_edge is None or inp.in_edge.rule.name=='phony' or inp.in_edge.index in done_edges or inp.in_edge.index not in self.plan_set) for inp in e.all_inputs_for_build):
                    wave.append(e)
            if not wave:
                raise NinjaError('dependency cycle or missing dependency')
            for e in wave:
                pending.remove(e)
            for e in wave:
                started += 1
                desc=edge_description(e, self.opts.get('verbose') or self.opts.get('dry_run'))
                if not self.opts.get('quiet'):
                    status = os.environ.get('NINJA_STATUS', '[%f/%t] ')
                    status = format_status(status, started, total, 1, total-started, finished)
                    out(status + desc + '\n')
                    sys.stdout.flush()
                cmd=edge_command(e)
                rc=0; output=b''
                st=time.time_ns()
                if not self.opts.get('dry_run'):
                    # response file support
                    rsp=expand_edge_binding(e, 'rspfile', shell_paths=False, raw_paths=True)
                    if rsp:
                        content=expand_edge_binding(e, 'rspfile_content', shell_paths=False, raw_paths=True)
                        with open(rsp, 'w', encoding='utf-8') as f: f.write(content)
                    p=subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
                    rc=p.returncode; output=p.stdout
                    if rc==0 and rsp and not self.opts.get('keeprsp'):
                        try: os.remove(rsp)
                        except OSError: pass
                en=time.time_ns()
                if output:
                    try: sys.stdout.write(output.decode('utf-8', 'replace'))
                    except Exception: sys.stdout.buffer.write(output)
                if rc != 0:
                    failed += 1; last_rc = rc if rc <= 125 else 1
                    if not self.opts.get('quiet'):
                        out(f"FAILED: [code={rc}] {' '.join(n.path for n in e.outputs)} \n{cmd}\n")
                    else:
                        out(f"FAILED: [code={rc}] {' '.join(n.path for n in e.outputs)} \n{cmd}\n")
                    if self.opts.get('keep_going',1) != 0 and failed >= self.opts.get('keep_going',1):
                        out('ninja: build stopped: subcommand failed.\n')
                        return last_rc or 1
                else:
                    if not self.opts.get('dry_run'):
                        append_log(self.m, e, st, en, cmd)
                done_edges.add(e.index); finished += 1
        if failed:
            out('ninja: build stopped: cannot make progress due to previous errors.\n')
            return last_rc or 1
        return 0

def format_status(fmt, s, t, r, u, f):
    pct = int((f*100)/t) if t else 100
    repl={'s':str(s),'t':str(t),'r':str(r),'u':str(u),'f':str(f),'p':str(pct)+'%','o':'0.0','c':'0.0','e':'0.000','E':'0.000','w':'0:00','W':'0:00','P':'0%','%':'%'}
    res=[]; i=0
    while i<len(fmt):
        if fmt[i]=='%' and i+1<len(fmt):
            res.append(repl.get(fmt[i+1], fmt[i+1])); i+=2
        else:
            res.append(fmt[i]); i+=1
    return ''.join(res)

def root_targets(m):
    roots=[]
    for e in m.edges:
        if e.rule.name == 'phony':
            # Phony edges can be roots too, but Ninja generally reports their
            # real dependencies when building; include them if explicit default.
            pass
        for n in e.outputs:
            consumed=False
            for oe in n.out_edges:
                if oe is not e:
                    consumed=True; break
            if not consumed:
                roots.append(n)
    return roots

def resolve_target(m, name, caret=False):
    if caret or name.endswith('^'):
        src = name[:-1] if name.endswith('^') else name
        for e in m.edges:
            for n in e.inputs:
                if n.path == src and e.outputs:
                    return e.outputs[0]
        return None
    if name in m.nodes: return m.nodes[name]
    return None

def suggest_target(m, name):
    # Tiny edit-distance-ish suggestion for the common shell split/misspell case.
    for p in m.nodes:
        if p.replace(' ', '') == name.replace(' ', '') or p.startswith(name) or name.startswith(p):
            return p
    return None

# ---------------- subtools ----------------

def topo_edges_for_targets(m, targets):
    seen=set(); order=[]
    def visit(n):
        e=n.in_edge
        if not e or e.index in seen: return
        seen.add(e.index)
        for inp in e.all_inputs_for_build:
            visit(inp)
        if e.rule.name != 'phony': order.append(e)
    for n in targets: visit(n)
    return order

def collect_inputs(n, include_intermediate=True, seen_edges=None, result=None):
    if seen_edges is None: seen_edges=set()
    if result is None: result=[]
    e=n.in_edge
    if not e: return result
    if e.index in seen_edges: return result
    seen_edges.add(e.index)
    for inp in e.dep_inputs:
        collect_inputs(inp, include_intermediate, seen_edges, result)
        if inp.path not in result:
            result.append(inp.path)
    return result

def tool_targets(m, args):
    mode='depth'; val='1'
    if args:
        if args[0] in ('all','depth','rule'):
            mode=args[0]; val=args[1] if len(args)>1 else ''
    if mode=='all':
        for e in m.edges:
            if e.rule.name=='phony': continue
            for n in e.all_outputs:
                out(f"{n.path}: {e.rule.name}\n")
        return 0
    if mode=='rule':
        if not val:
            # source files/leaves
            for n in m.nodes.values():
                if n.in_edge is None and n.out_edges:
                    out(n.path+'\n')
        else:
            for e in m.edges:
                if e.rule.name==val:
                    for n in e.outputs: out(n.path+'\n')
        return 0
    try: depth=int(val)
    except Exception: depth=1
    roots=root_targets(m)
    def rec(n, ind, d):
        e=n.in_edge
        if not e: return
        out('  '*ind + f"{n.path}: {e.rule.name}\n")
        if depth!=0 and d>=depth: return
        for inp in e.dep_inputs + e.order_only:
            if inp.in_edge: rec(inp, ind+1, d+1)
    for r in roots: rec(r,0,1)
    return 0

def tool_rules(m, args):
    for name in m.rules.keys():
        out(name+'\n')
    return 0

def tool_query(m, args):
    if not args:
        eprint('ninja: error: expected a target to query\n'); return 1
    rc=0
    for name in args:
        n=resolve_target(m,name)
        if not n:
            eprint(f"ninja: error: unknown target '{name}'\n"); return 1
        out(f"{n.path}:\n")
        if n.in_edge:
            e=n.in_edge
            out(f"  input: {e.rule.name}\n")
            for inp in e.inputs: out(f"    {inp.path}\n")
            for inp in e.implicit_inputs: out(f"    | {inp.path}\n")
            for inp in e.order_only: out(f"    || {inp.path}\n")
        out('  outputs:\n')
        for oe in n.out_edges:
            for o in oe.outputs:
                out(f"    {o.path}\n")
    return rc

def target_nodes_from_args(m, args, require=True):
    if not args:
        return m.defaults if m.defaults else root_targets(m)
    res=[]
    for a in args:
        n=resolve_target(m,a)
        if not n:
            sug=suggest_target(m,a)
            if sug:
                eprint(f"ninja: error: unknown target '{a}', did you mean '{sug}'?\n")
            else:
                eprint(f"ninja: error: unknown target '{a}'\n")
            return None
        res.append(n)
    return res

def tool_commands(m, args):
    final_only=False
    if args and args[0]=='-s': final_only=True; args=args[1:]
    targets=target_nodes_from_args(m,args)
    if targets is None: return 1
    edges=topo_edges_for_targets(m,targets)
    if final_only:
        final=set(n.in_edge.index for n in targets if n.in_edge and n.in_edge.rule.name!='phony')
        edges=[e for e in edges if e.index in final]
    for e in edges:
        out(edge_command(e)+'\n')
    return 0

def tool_inputs(m, args):
    shell=True; dep_order=False; term='\n'
    if args and args[0] in ('-h','--help'):
        out("""Usage '-t inputs [options] [targets]

List all inputs used for a set of targets, sorted in dependency order.
Note that by default, results are shell escaped, and sorted alphabetically,
and never include validation target paths.

Options:
  -h, --help          Print this message.
  -0, --print0            Use \\0, instead of \\n as a line terminator.
  -E, --no-shell-escape   Do not shell escape the result.
  -d, --dependency-order  Sort results by dependency order.
"""); return 1
    rest=[]; i=0
    while i<len(args):
        a=args[i]
        if a in ('-E','--no-shell-escape'): shell=False
        elif a in ('-d','--dependency-order'): dep_order=True
        elif a in ('-0','--print0'): term='\0'
        else: rest.append(a)
        i+=1
    targets=target_nodes_from_args(m,rest)
    if targets is None: return 1
    vals=[]
    for n in targets:
        collect_inputs(n, True, set(), vals)
    if not dep_order:
        vals=sorted(set(vals))
    for v in vals:
        out((shell_escape_path(v) if shell else v)+term)
    return 0

def tool_multi_inputs(m, args):
    delim='\t'; term='\n'; rest=[]; i=0
    while i<len(args):
        a=args[i]
        if a.startswith('--delimiter='): delim=a.split('=',1)[1]
        elif a=='--delimiter' and i+1<len(args): i+=1; delim=args[i]
        elif a in ('-0','--print0'): term='\0'
        else: rest.append(a)
        i+=1
    targets=target_nodes_from_args(m,rest)
    if targets is None: return 1
    for n in targets:
        vals=[]; collect_inputs(n, True, set(), vals)
        for v in vals:
            out(n.path+delim+v+term)
    return 0

def tool_compdb(m, args, by_targets=False):
    expand_rsp=False
    if args and args[0]=='-x': expand_rsp=True; args=args[1:]
    edges=[]
    if by_targets:
        if not args:
            eprint('ninja: error: compdb-targets expects at least one target\n'); return 1
        targets=target_nodes_from_args(m,args)
        if targets is None: return 1
        edges=topo_edges_for_targets(m,targets)
    else:
        wanted=set(args)
        for e in m.edges:
            if e.rule.name in wanted: edges.append(e)
    entries=[]; cwd=os.getcwd()
    for e in edges:
        cmd=edge_command(e)
        if expand_rsp:
            rsp=expand_edge_binding(e,'rspfile',shell_paths=False,raw_paths=True)
            if rsp and os.path.exists(rsp):
                try: content=open(rsp).read()
                except OSError: content=''
                cmd=cmd.replace('@'+rsp, content)
        for inp in e.inputs + e.implicit_inputs:
            entries.append({'directory':cwd,'command':cmd,'file':inp.path,'output':e.outputs[0].path if e.outputs else ''})
    out(json.dumps(entries, indent=2) + '\n')
    return 0

def tool_clean(m, args, opts):
    generator=False; by_rule=False; targets=[]
    i=0
    while i<len(args):
        a=args[i]
        if a=='-g': generator=True
        elif a=='-r': by_rule=True
        elif a.startswith('-'):
            out('usage: ninja -t clean [options] [targets]\n\noptions:\n  -g     also clean files marked as ninja generator output\n  -r     interpret targets as a list of rules to clean instead\n')
            eprint(f"clean: invalid option -- '{a.lstrip('-')}'\n")
            return 1
        else: targets.append(a)
        i+=1
    files=[]
    def add_edge(e):
        if e.rule.name=='phony': return
        gen=edge_lookup(e,'generator')=='1'
        if gen and not generator: return
        for n in e.all_outputs:
            if n.path not in files: files.append(n.path)
    if by_rule:
        rules=set(targets)
        for e in m.edges:
            if e.rule.name in rules: add_edge(e)
    elif targets:
        seen=set()
        def rec(n):
            e=n.in_edge
            if not e or e.index in seen: return
            seen.add(e.index); add_edge(e)
            for inp in e.dep_inputs: rec(inp)
        for t in targets:
            n=resolve_target(m,t)
            if n: rec(n)
    else:
        for e in m.edges: add_edge(e)
    verbose=opts.get('verbose') or opts.get('dry_run')
    if verbose:
        out('Cleaning...\n')
    removed=0
    for f in files:
        if os.path.exists(f):
            removed += 1
            if verbose: out('Remove '+f+'\n')
            if not opts.get('dry_run'):
                try: os.remove(f)
                except IsADirectoryError:
                    try: os.rmdir(f)
                    except OSError: pass
                except OSError: pass
    if verbose: out(f"{removed} files.\n")
    else: out(f"Cleaning... {removed} files.\n")
    return 0

def tool_graph(m,args):
    targets=target_nodes_from_args(m,args) if args else root_targets(m)
    if targets is None: return 1
    out('digraph ninja {\nrankdir="LR"\nnode [fontsize=10, shape=box, height=0.25]\nedge [fontsize=10]\n')
    ids={}; counter=[0]
    def nid(obj):
        key=id(obj)
        if key not in ids:
            ids[key]=f"0x{counter[0]:x}"; counter[0]+=1
        return ids[key]
    seen=set()
    def rec(n):
        out(f'"{nid(n)}" [label="{n.path}"]\n')
        e=n.in_edge
        if not e or e.index in seen: return
        seen.add(e.index)
        out(f'"{nid(e)}" [label="{e.rule.name}", shape=ellipse]\n')
        out(f'"{nid(e)}" -> "{nid(n)}"\n')
        for inp in e.dep_inputs:
            rec(inp); out(f'"{nid(inp)}" -> "{nid(e)}"\n')
    for t in targets: rec(t)
    out('}\n'); return 0

def tool_deps(m,args):
    if args:
        for a in args: out(f"{a}: deps not found\n")
    return 0

def dispatch_tool(m, tool, args, opts):
    if tool=='list': out(TOOL_LIST); return 0
    if tool=='targets': return tool_targets(m,args)
    if tool=='rules': return tool_rules(m,args)
    if tool=='query': return tool_query(m,args)
    if tool=='commands': return tool_commands(m,args)
    if tool=='inputs': return tool_inputs(m,args)
    if tool=='multi-inputs': return tool_multi_inputs(m,args)
    if tool=='compdb': return tool_compdb(m,args,False)
    if tool=='compdb-targets': return tool_compdb(m,args,True)
    if tool=='clean': return tool_clean(m,args,opts)
    if tool=='graph': return tool_graph(m,args)
    if tool=='deps': return tool_deps(m,args)
    if tool=='missingdeps': out(f"Processed {len(m.nodes)} nodes.\nNo missing dependencies on generated files found.\n"); return 0
    if tool in ('recompact','restat'): return 0
    if tool=='cleandead': out('Cleaning... 0 files.\n'); return 0
    if tool=='browse': eprint('ninja: error: browse tool is not available in this reimplementation\n'); return 1
    eprint(f"ninja: error: unknown tool '{tool}'\n"); return 1

# ---------------- main ----------------

def parse_args(argv):
    opts={'file':'build.ninja','verbose':False,'quiet':False,'dry_run':False,'jobs':None,'keep_going':1,'debug':set(),'warnings':{},'tool':None,'tool_args':[],'chdir':None,'keeprsp':False}
    targets=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a=='--version': print(VERSION); sys.exit(0)
        if a in ('-h','--help'):
            eprint(HELP); sys.exit(1)
        if a in ('-v','--verbose'): opts['verbose']=True; i+=1; continue
        if a=='--quiet': opts['quiet']=True; i+=1; continue
        if a=='-n' or a=='--dry-run': opts['dry_run']=True; i+=1; continue
        if a.startswith('-C'):
            if a=='-C':
                i+=1
                if i>=len(argv): option_requires('C')
                opts['chdir']=argv[i]
            else: opts['chdir']=a[2:]
            i+=1; continue
        if a.startswith('-f'):
            if a=='-f':
                i+=1
                if i>=len(argv): option_requires('f')
                opts['file']=argv[i]
            else: opts['file']=a[2:]
            i+=1; continue
        if a.startswith('-j'):
            val = None
            if a=='-j':
                i+=1
                if i>=len(argv): option_requires('j')
                val=argv[i]
            else: val=a[2:]
            try: opts['jobs']=int(val)
            except Exception:
                eprint('ninja: fatal: invalid -j parameter\n'); sys.exit(1)
            i+=1; continue
        if a.startswith('-k'):
            val=None
            if a=='-k':
                i+=1
                if i>=len(argv): option_requires('k')
                val=argv[i]
            else: val=a[2:]
            try: opts['keep_going']=int(val)
            except Exception:
                eprint('ninja: fatal: invalid -k parameter\n'); sys.exit(1)
            i+=1; continue
        if a.startswith('-l'):
            if a=='-l': i+=2
            else: i+=1
            continue
        if a=='-d':
            i+=1
            if i>=len(argv): option_requires('d')
            if argv[i]=='list': out(DEBUG_LIST); sys.exit(1)
            opts['debug'].add(argv[i])
            if argv[i]=='keeprsp': opts['keeprsp']=True
            i+=1; continue
        if a.startswith('-d') and len(a)>2:
            mode=a[2:]
            if mode=='list': out(DEBUG_LIST); sys.exit(1)
            opts['debug'].add(mode); i+=1; continue
        if a=='-w':
            i+=1
            if i>=len(argv): option_requires('w')
            if argv[i]=='list': out(WARN_LIST); sys.exit(1)
            i+=1; continue
        if a.startswith('-w') and len(a)>2:
            if a[2:]=='list': out(WARN_LIST); sys.exit(1)
            i+=1; continue
        if a=='-t':
            i+=1
            if i>=len(argv): option_requires('t')
            opts['tool']=argv[i]; opts['tool_args']=argv[i+1:]
            return opts, targets
        if a.startswith('-t') and len(a)>2:
            opts['tool']=a[2:]; opts['tool_args']=argv[i+1:]
            return opts, targets
        if a.startswith('-') and a!='-':
            eprint(f"{sys.argv[0]}: invalid option -- '{a.lstrip('-')[0]}'\n")
            eprint(HELP); sys.exit(1)
        targets.append(a); i+=1
    return opts, targets

def option_requires(ch):
    eprint(f"{sys.argv[0]}: option requires an argument -- '{ch}'\n")
    eprint(HELP); sys.exit(1)

def main(argv):
    opts, target_args = parse_args(argv)
    if opts.get('chdir'):
        try: os.chdir(opts['chdir'])
        except OSError as e:
            eprint(f"ninja: Entering directory `{opts['chdir']}'\n")
            eprint(f"ninja: fatal: chdir to '{opts['chdir']}' - {e.strerror}\n")
            return 1
        if not opts.get('quiet'):
            out(f"ninja: Entering directory `{opts['chdir']}'\n")
    m=Manifest(); p=Parser(m)
    try:
        p.parse_file(opts['file'], m.root_env)
    except NinjaError as e:
        eprint('ninja: error: '+str(e)+'\n'); return 1
    if opts.get('tool'):
        return dispatch_tool(m, opts['tool'], opts.get('tool_args',[]), opts)
    nodes=[]
    for a in target_args:
        n=resolve_target(m,a)
        if not n:
            sug=suggest_target(m,a)
            if sug: eprint(f"ninja: error: unknown target '{a}', did you mean '{sug}'?\n")
            else: eprint(f"ninja: error: unknown target '{a}'\n")
            return 1
        nodes.append(n)
    try:
        return Builder(m,opts).build(nodes)
    except NinjaError as e:
        eprint('ninja: error: '+str(e)+'\n'); return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
